/* Draw-only benchmark: the production renderer, same fixture and flags on both
 * source trees. Host CPU timings are comparisons, not device frame-time claims. */
#define SMC_UI_MAIN unused_smc_ui_main
#ifndef NIGHT_UI_SMC_FIXTURE
#define NIGHT_UI_SMC_FIXTURE "smc_ui_test.c"
#endif
#include NIGHT_UI_SMC_FIXTURE

static double cpu_ms(void)
{
    struct timespec t;
    clock_gettime(CLOCK_PROCESS_CPUTIME_ID,&t);
    return (double)t.tv_sec*1000.0+(double)t.tv_nsec/1000000.0;
}
static void paint(void) { draw_header();draw_main();draw_knobs(); }
static void measure(const char *name)
{
    enum { N=200 };
    project_t *p=malloc(sizeof proj);
    CHECK(p!=NULL);memcpy(p,&proj,sizeof proj);
    seq_t s=seq;
    paint();
    uint32_t b=blits;
    paint();
    CHECK(blits==b); /* a static page must still send no SPI rectangle */
    double t=cpu_ms();
    for(int i=0;i<N;i++) { memset(blit_hash,0,sizeof blit_hash);paint(); }
    double full=(cpu_ms()-t)/N;
    t=cpu_ms();b=blits;
    for(int i=0;i<N;i++)paint();
    double steady=(cpu_ms()-t)/N;
    CHECK(blits==b);
    CHECK(!memcmp(p,&proj,sizeof proj) && !memcmp(&s,&seq,sizeof seq));
    printf("DRAW_COST %s full_ms=%.6f steady_ms=%.6f static_blits=%u frames=%u\n",name,full,steady,blits-b,N);
    free(p);
}
int main(void)
{
    setup(V_HOME,PART_909);measure("HOME");
    for(int p=0;p<NPARTS;p++) {
        setup(V_PART,p);measure(part_s(p));
        if(p==PART_303A || p==PART_303B) {
            *page_of(V_PART)=pg.n-1;build_pages();measure(p==PART_303A?"MIAMI_SOUND":"CHICAGO_SOUND");
        }
    }
    setup(V_FX,PART_303B);measure("FX");
    setup(V_MIX,PART_303B);measure("MIX");
    *page_of(V_MIX)=4;build_pages();measure("WAVE");
    setup(V_SONG,PART_303B);song_fill(0);measure("SONG");
    setup(V_SEQ,PART_909);measure("DRUM_SEQ");
    setup(V_SEQ,PART_303B);measure("SYNTH_SEQ");
    setup(V_HOME,PART_303B);open_global();measure("GLOBAL");
    printf("night_ui_bench: PASS (%u cache/nonmutation checks)\n",checks);
    return 0;
}

/* SPDX-License-Identifier: GPL-3.0-only */
/* lz.c (the project's packed patterns, song and motion): every input comes back exactly, through
 * the sink and the source a byte at a time; a refusing sink stops it; a short or broken stream is
 * refused, never written past its end. */
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include "../../firmware/src/app/lz.c"

#define MAXN 60000u
static uint8_t in[MAXN], packed[MAXN + MAXN / 64u + 16u], out[MAXN + 64u];
static uint32_t npacked, cap;

static int put(void *ctx, const uint8_t *p, uint32_t n)
{
    (void)ctx;
    if (npacked + n > cap)
        return -1;
    memcpy(packed + npacked, p, n);
    npacked += n;
    return 0;
}

typedef struct { uint32_t pos, n; } src_t;
static int get(void *ctx)
{
    src_t *s = ctx;
    return s->pos < s->n ? packed[s->pos++] : -1;
}

static uint32_t rng = 12345u;
static uint32_t rnd(void)
{
    rng ^= rng << 13;
    rng ^= rng >> 17;
    rng ^= rng << 5;
    return rng;
}

static int bad;
static void roundtrip(const char *name, uint32_t n)
{
    lz_sink_t sink = {put, 0};
    src_t s = {0, 0};
    lz_src_t src = {get, &s};
    npacked = 0;
    cap = sizeof packed;
    if (lz_compress(in, n, &sink)) {
        printf("FAIL %s: compress refused\n", name);
        bad = 1;
        return;
    }
    s.n = npacked;
    memset(out, 0xA5, sizeof out);
    if (lz_decompress(&src, out, n) || memcmp(in, out, n) || out[n] != 0xA5) {
        printf("FAIL %s: %u bytes do not come back\n", name, n);
        bad = 1;
        return;
    }
    if (n && s.pos != npacked) {
        printf("FAIL %s: %u of %u packed bytes read\n", name, s.pos, npacked);
        bad = 1;
        return;
    }
    if (name[0])
        printf("  ok %-28s %6u -> %6u\n", name, n, npacked);
}

int main(void)
{
    uint32_t i, n;
    roundtrip("empty", 0);
    in[0] = 7;
    roundtrip("one byte", 1);
    memset(in, 0, MAXN);
    roundtrip("zeros", 30000);
    for (i = 0; i < MAXN; i++)
        in[i] = (uint8_t)rnd();
    roundtrip("random (incompressible)", 30000);
    roundtrip("random, near the limit", MAXN);
    for (n = 1; n < 400; n++) {                       /* every literal / match length boundary */
        for (i = 0; i < n; i++)
            in[i] = (uint8_t)(rnd() % 3u);
        npacked = 0;
        roundtrip(n == 399 ? "small alphabet 1..399" : "", n);
        if (bad)
            break;
    }
    for (i = 0; i < 30000; i++)                       /* a pattern-like layout: sparse rows, repeats */
        in[i] = (i % 528u) < 100u ? (uint8_t)((i * 7u) % 5u == 0 ? 0x11 : 0) : (uint8_t)(i % 528u > 400 ? 45 : 0);
    roundtrip("structured", 30000);
    {                                                 /* a sink that fills up stops the compressor */
        lz_sink_t sink = {put, 0};
        for (i = 0; i < 30000; i++)
            in[i] = (uint8_t)rnd();
        npacked = 0;
        cap = 1000;
        if (!lz_compress(in, 30000, &sink)) {
            printf("FAIL a full sink did not stop it\n");
            bad = 1;
        }
    }
    {                                                 /* a short stream: refused, nothing past the end */
        lz_sink_t sink = {put, 0};
        src_t s = {0, 0};
        lz_src_t src = {get, &s};
        for (i = 0; i < 5000; i++)
            in[i] = (uint8_t)(i / 50u);
        npacked = 0;
        cap = sizeof packed;
        lz_compress(in, 5000, &sink);
        s.n = npacked / 2u;
        memset(out, 0xA5, sizeof out);
        if (!lz_decompress(&src, out, 5000) || out[5000] != 0xA5) {
            printf("FAIL a short stream was taken\n");
            bad = 1;
        }
        s.pos = 0;                                    /* a distance before the start */
        s.n = 4;
        packed[0] = 0x80;
        packed[1] = 0x10;
        packed[2] = 0x00;
        packed[3] = 0x00;
        if (!lz_decompress(&src, out, 100)) {
            printf("FAIL a match before the start was taken\n");
            bad = 1;
        }
    }
    {                                                 /* an input too long for 16-bit positions: refused */
        lz_sink_t sink = {put, 0};
        npacked = 0;
        cap = sizeof packed;
        if (!lz_compress(in, 0xFFFFu, &sink)) {
            printf("FAIL 64 KB taken\n");
            bad = 1;
        }
    }
    printf(bad ? "LZ FAILED\n" : "lz: all ok\n");
    return bad;
}

