/* The few libc routines the compiler may call implicitly (struct copies,
 * zeroing). Freestanding: no other libc. */
void *memset(void *d, int c, unsigned n)
{
    unsigned char *p = d;
    while (n--)
        *p++ = (unsigned char)c;
    return d;
}

void *memcpy(void *d, const void *s, unsigned n)
{
    unsigned char *p = d;
    const unsigned char *q = s;
    while (n--)
        *p++ = *q++;
    return d;
}

int memcmp(const void *a, const void *b, unsigned n)
{
    const unsigned char *p = a, *q = b;
    for (; n; n--, p++, q++)
        if (*p != *q)
            return *p - *q;
    return 0;
}

static int str_eq(const char *a, const char *b)
{
    while (*a && *a == *b) {
        a++;
        b++;
    }
    return *a == *b;
}

static unsigned str_len(const char *s)
{
    unsigned n = 0;
    while (s[n])
        n++;
    return n;
}

static void str_cpy(char *d, const char *s, unsigned max)
{
    unsigned i = 0;
    while (s[i] && i + 1 < max) {
        d[i] = s[i];
        i++;
    }
    d[i] = 0;
}

/* decimal with an optional fixed point: fmt_fix(buf, -63, 1) -> "-6.3" */
static void fmt_fix(char *b, int32_t v, int decimals)
{
    char t[12];
    int n = 0, neg = v < 0, i;
    uint32_t u = (uint32_t)(neg ? -v : v);
    do {
        t[n++] = (char)('0' + u % 10u);
        u /= 10u;
        if (n == decimals)
            t[n++] = '.';
    } while (u || n <= decimals);
    if (neg)
        t[n++] = '-';
    for (i = 0; i < n; i++)
        b[i] = t[n - 1 - i];
    b[n] = 0;
}

static void fmt_int(char *b, int32_t v) { fmt_fix(b, v, 0); }

static uint32_t rng_state = 0x1234567u;
static uint32_t rng(void)
{
    rng_state ^= rng_state << 13;
    rng_state ^= rng_state >> 17;
    rng_state ^= rng_state << 5;
    return rng_state;
}

/* SPDX-License-Identifier: GPL-3.0-only */
/* Chicago Fx Type = Phaser — per-voice insert (not SEND / Mix theft).
 *
 * Factory Phaser rows (Hot Tube, Phase Line, Phaze Craze, RAZR FX) need moving
 * notches on the dry 303 voice for strong-relative spectrum. AU compare
 * previously rendered dry native303 while Phaser stayed NOT_YET.
 *
 * Compact mono 4-stage first-order allpass + mild feedback. Edit1 → linear wet
 * (no floor — Phase Line Edit1≈41 stays light; Hot Tube≈95 still thick).
 * Edit2 → LFO rate/depth + feedback. No delay-line pool hit; no libm. */
#pragma once
#include <stdint.h>
#include <string.h>
#include "../dsp/fastmath.h"
#include "chicago_fx.h"

#ifndef CHI_PHASER_SR
#define CHI_PHASER_SR 44100.0f
#endif

#define CHI_PHASER_STAGES 4

typedef struct {
    float z[CHI_PHASER_STAGES]; /* allpass delay states */
    float last_y;               /* previous chain out (feedback) */
    float phase;                /* LFO phase in turns 0..1 */
    float inc;                  /* LFO turns per sample */
    float g_centre;             /* allpass coeff centre */
    float g_depth;              /* ± LFO sweep of coeff */
    float fb;                   /* feedback into first stage */
    float wet;                  /* 0 dry .. 1 full insert */
} chi_phaser_t;

static inline void chi_phaser_set(chi_phaser_t *p, uint8_t e1, uint8_t e2, float sr)
{
    float send, t, rate_hz;
    if (!p)
        return;
    if (sr < 1.0f)
        sr = CHI_PHASER_SR;
    send = (float)e1 * (1.0f / 127.0f);
    t = (float)e2 * (1.0f / 127.0f);
    /* Linear wet (no floor): Phase Line Edit1≈41 → ~0.32; Hot Tube≈95 → ~0.75. */
    p->wet = send;
    /* Edit2 mid (Hot Tube≈64): gentle sweep; high → faster/deeper whoosh. */
    rate_hz = 0.10f + 1.8f * t;
    p->g_centre = 0.40f + 0.28f * t; /* ~0.40..0.68 */
    p->g_depth = 0.10f + 0.22f * t;  /* keep |g| in ~0.1..0.90 */
    p->fb = 0.02f + 0.28f * t;
    p->inc = rate_hz / sr;
    if (p->inc > 0.05f)
        p->inc = 0.05f;
}

static inline void chi_phaser_init(chi_phaser_t *p)
{
    if (!p)
        return;
    memset(p->z, 0, sizeof(p->z));
    p->last_y = 0.0f;
    p->phase = 0.0f;
    p->inc = 0.0f;
    p->g_centre = 0.55f;
    p->g_depth = 0.20f;
    p->fb = 0.0f;
    p->wet = 0.0f;
}

/* One first-order allpass: y = -g·x + z; z = x + g·y */
static inline float chi_phaser_ap(float x, float g, float *z)
{
    float y = -g * x + *z;
    *z = x + g * y;
    return y;
}

/* In-place mono insert. wet=0 is a no-op. */
static inline void chi_phaser_process(chi_phaser_t *p, float *buf, int n)
{
    float wet, dry_g, ph, inc, g0, gd, fb;
    int k, s;
    if (!p || !buf || n <= 0)
        return;
    wet = p->wet;
    if (wet <= 0.0f)
        return;
    dry_g = 1.0f - wet;
    ph = p->phase;
    inc = p->inc;
    g0 = p->g_centre;
    gd = p->g_depth;
    fb = p->fb;
    for (k = 0; k < n; k++) {
        float x = buf[k];
        float lfo, g, y, in;
        lfo = fm_sin_turns(ph);
        ph += inc;
        if (ph >= 1.0f)
            ph -= 1.0f;
        g = g0 + gd * lfo;
        if (g > 0.95f)
            g = 0.95f;
        else if (g < 0.05f)
            g = 0.05f;
        in = x + fb * p->last_y;
        if (in > 1.0f)
            in = 1.0f;
        else if (in < -1.0f)
            in = -1.0f;
        y = in;
        for (s = 0; s < CHI_PHASER_STAGES; s++)
            y = chi_phaser_ap(y, g, &p->z[s]);
        p->last_y = y;
        buf[k] = dry_g * x + wet * y;
    }
    p->phase = ph;
}

static inline int chi_fx_is_phaser_insert(uint8_t type)
{
    return type == CHI_FX_PHASER;
}

#!/usr/bin/env python3
"""Guard: engine_brk_outline must clamp abs(-32768) before uint8 store."""
from __future__ import annotations

import pathlib
import re
import sys

ROOT = pathlib.Path(__file__).resolve().parents[2]
ENGINE = ROOT / "firmware/src/app/engine.c"


def fail(msg: str) -> None:
    print(f"FAIL: {msg}", file=sys.stderr)
    raise SystemExit(1)


def main() -> None:
    text = ENGINE.read_text()
    if "brk_outline_peak_u8" not in text:
        fail("engine.c missing brk_outline_peak_u8 clamp helper")

    m = re.search(
        r"static\s+uint8_t\s+brk_outline_peak_u8\s*\(\s*int32_t\s+pk\s*\)\s*\{(.*?)\}",
        text,
        re.S,
    )
    if not m:
        fail("brk_outline_peak_u8 definition not found")
    body = m.group(1)
    if "32768" not in body or "255" not in body:
        fail("brk_outline_peak_u8 must clamp pk >= 32768 to 255")

    m = re.search(
        r"X0X_COLD\s+int\s+engine_brk_outline\s*\(.*?\)\s*\{(.*?)^\}",
        text,
        re.S | re.M,
    )
    if not m:
        fail("engine_brk_outline not found")
    fn = m.group(1)
    if fn.count("brk_outline_peak_u8") < 2:
        fail("engine_brk_outline must store peaks through brk_outline_peak_u8 twice")
    if re.search(r"peaks\[[^\]]+\]\s*=\s*\(uint8_t\)\s*\(\s*pk\s*>>\s*7\s*\)", fn):
        fail("engine_brk_outline still has unclamped (uint8_t)(pk >> 7) store")

    print("PASS: engine_brk_outline clamps negative full-scale peaks")


if __name__ == "__main__":
    main()

