/* SPDX-License-Identifier: GPL-3.0-only */
/* Per-bus momentary FX and channel cutoff. One-pole filters, decay and tempo-synced
 * rhythm gates, stutter, and shuffle. Reverb and delay throws are send levels
 * (busfx_send); the existing fxbus keeps the tail. Effect ids match smc_fx_map.h. */
#pragma once
#include "fastmath.h"

enum {
    BFX_GATE = 0,
    BFX_REV = 1,
    BFX_HP = 2,
    BFX_DLY = 3,
    BFX_LP = 4,
    BFX_GATE8 = 5,
    BFX_GATE16 = 6,
    BFX_TRANCE = 7,
    BFX_STUT = 8,
    BFX_SHUF = 9,
    BFX_NFX = 10
};

#define BFX_RING 2u
#define BFX_STUT_CH 12u
#define BFX_SEND_NOM 0.4f
#define BFX_STUT_SCALE 32767.0f

typedef struct {
    int16_t ring[BFX_STUT_CH][BFX_RING];
    uint8_t ring_w[BFX_STUT_CH];
} busfx_stut_hub_t;

typedef busfx_stut_hub_t busfx_stut_t;

/* One state shape for 1..4 channels (send throws use nch=1, master filter nch=2,
 * drum buses up to 4). Sharing one apply body beats three near-copies. */
typedef struct {
    float a;
    float lp[4];
    float hp[4];
    float tone_lp[4];
    float hp_mix;
    float lp_mix;
    float gate;
    float follow;
} busfx_t;

static inline void busfx_init(busfx_t *s)
{
    unsigned i;
    uint8_t *p = (uint8_t *)s;
    for (i = 0; i < sizeof *s; i++)
        p[i] = 0;
    s->a = 1.0f;
    s->gate = 1.0f;
}

static inline void busfx_stut_init(busfx_stut_t *st)
{
    unsigned i;
    uint8_t *p;
    if (!st)
        return;
    p = (uint8_t *)st;
    for (i = 0; i < sizeof *st; i++)
        p[i] = 0;
}

static inline int busfx_is_decay_gate(int effect) { return effect == BFX_GATE; }

static inline int busfx_is_rhythm(int effect)
{
    return effect == BFX_GATE8 || effect == BFX_GATE16 || effect == BFX_TRANCE || effect == BFX_STUT ||
           effect == BFX_SHUF;
}

static inline int busfx_settling(const busfx_t *s)
{
    return s->gate < 0.9995f || s->hp_mix > 0.002f || s->lp_mix > 0.002f || s->a < 0.9995f;
}

static inline float busfx_bpm_clamp(float bpm)
{
    if (bpm < 20.0f)
        bpm = 20.0f;
    if (bpm > 300.0f)
        bpm = 300.0f;
    return bpm;
}

static inline uint32_t busfx_sp16(float bpm)
{
    bpm = busfx_bpm_clamp(bpm);
    return (uint32_t)(44100.0f * 15.0f / bpm + 0.5f);
}

static inline uint32_t busfx_sp8(float bpm)
{
    return busfx_sp16(bpm) * 2u;
}

static inline float busfx_rhythm_target(int effect, float bpm, uint32_t abs_s)
{
    uint32_t sp16 = busfx_sp16(bpm), sp8 = busfx_sp8(bpm), period, pos, sixteenth;
    float ph, duty = 0.5f;
    if (sp16 < 32u)
        sp16 = 32u;
    if (effect == BFX_GATE8) {
        period = sp8;
        duty = 0.5f;
    } else if (effect == BFX_GATE16 || effect == BFX_STUT) {
        period = sp16;
        duty = (effect == BFX_STUT) ? 0.22f : 0.5f;
    } else if (effect == BFX_TRANCE) {
        period = sp16;
        duty = 0.38f;
    } else if (effect == BFX_SHUF) {
        sixteenth = abs_s / sp16;
        pos = abs_s % sp16;
        ph = (float)pos / (float)sp16;
        if (sixteenth & 1u)
            ph -= 0.34f;
        if (ph < 0.0f)
            ph = 0.0f;
        return ph < 0.48f ? 1.0f : 0.0f;
    } else
        return 1.0f;
    pos = abs_s % period;
    ph = (float)pos / (float)period;
    return ph < duty ? 1.0f : 0.0f;
}

static inline void busfx_ring_write(busfx_stut_t *st, int ch, float x)
{
    uint8_t w;
    float s;
    if (!st || ch < 0 || ch >= (int)BFX_STUT_CH)
        return;
    w = st->ring_w[ch];
    s = x * BFX_STUT_SCALE;
    if (s > 32767.0f)
        s = 32767.0f;
    else if (s < -32768.0f)
        s = -32768.0f;
    st->ring[ch][w] = (int16_t)s;
    st->ring_w[ch] = (uint8_t)((w + 1u) % BFX_RING);
}

static inline float busfx_ring_read(const busfx_stut_t *st, int ch, uint8_t back)
{
    int idx;
    if (!st || ch < 0 || ch >= (int)BFX_STUT_CH)
        return 0.0f;
    idx = (int)st->ring_w[ch] - 1 - (int)back;
    while (idx < 0)
        idx += (int)BFX_RING;
    return (float)st->ring[ch][(unsigned)idx] * (1.0f / BFX_STUT_SCALE);
}

static inline float busfx_send(float saved, int held, int effect, int which)
{
    if (held && effect == which)
        return 1.0f;
    return saved < 0.0f ? 0.0f : saved;
}

/* One body for every bus width — callers must not inline three copies. */
static __attribute__((noinline)) void busfx_apply(busfx_t *s, busfx_stut_t *stut, int stut_base, float *c0,
                                                  float *c1, float *c2, float *c3, int nch, int n, float cut,
                                                  int held0, int effect, int press_at, int release_at, float bpm,
                                                  uint32_t sample0)
{
    float *ch[4];
    int i, k, held = held0 ? 1 : 0;
    const float slew = 0.0022651f;
    const float hp_c = 0.0395f;
    const float rg_a = 0.35f;
    const float rg_r = 0.18f;
    ch[0] = c0;
    ch[1] = c1;
    ch[2] = c2;
    ch[3] = c3;
    if (nch < 1)
        nch = 1;
    if (nch > 4)
        nch = 4;
    if (press_at < 0)
        press_at = n;
    if (release_at < 0)
        release_at = n;
    bpm = busfx_bpm_clamp(bpm);
    for (i = 0; i < n; i++) {
        float target, want_hp, want_lp, peak = 0.0f, rg_tgt = 1.0f;
        uint32_t abs_s = sample0 + (uint32_t)i;
        if (i == press_at)
            held = 1;
        if (i == release_at)
            held = 0;
        if (cut >= 126.5f)
            target = 1.0f;
        else {
            float fc = 40.0f * fm_exp2f(cut * (8.2f / 127.0f));
            target = 1.0f - fm_expf(-2.0f * FM_PI * fc / 44100.0f);
            if (target > 1.0f)
                target = 1.0f;
        }
        s->a += (target - s->a) * slew;
        if (fm_fabsf(target - s->a) < 1.0e-4f)
            s->a = target;
        want_hp = (held && effect == BFX_HP) ? 1.0f : 0.0f;
        s->hp_mix += (want_hp - s->hp_mix) * 0.01f;
        if (fm_fabsf(want_hp - s->hp_mix) < 1.0e-4f)
            s->hp_mix = want_hp;
        want_lp = (held && effect == BFX_LP) ? 1.0f : 0.0f;
        s->lp_mix += (want_lp - s->lp_mix) * 0.01f;
        if (fm_fabsf(want_lp - s->lp_mix) < 1.0e-4f)
            s->lp_mix = want_lp;
        if (held && busfx_is_rhythm(effect))
            rg_tgt = busfx_rhythm_target(effect, bpm, abs_s);
        if (!(held && (busfx_is_decay_gate(effect) || busfx_is_rhythm(effect)))) {
            s->gate += (1.0f - s->gate) * 0.02f;
            if (s->gate > 0.999f)
                s->gate = 1.0f;
        }
        for (k = 0; k < nch; k++) {
            float x = ch[k][i], y, hp, ax;
            if (s->a >= 0.999f) {
                s->lp[k] = x;
                y = x;
            } else {
                s->lp[k] += (x - s->lp[k]) * s->a;
                y = s->lp[k];
            }
            s->hp[k] += (y - s->hp[k]) * hp_c;
            s->tone_lp[k] += (x - s->tone_lp[k]) * 0.008f;
            hp = y - s->hp[k];
            if (s->hp_mix > 0.0f)
                y += (hp - y) * s->hp_mix;
            if (s->lp_mix > 0.0f)
                y += (s->tone_lp[k] - y) * s->lp_mix;
            ax = fm_fabsf(y);
            if (ax > peak)
                peak = ax;
            if (held && effect == BFX_STUT && stut) {
                int ring_ch = stut_base + k;
                uint32_t sp16 = busfx_sp16(bpm);
                uint32_t pos = abs_s % sp16;
                uint32_t chunk = sp16 / 4u;
                if (chunk < 8u)
                    chunk = 8u;
                busfx_ring_write(stut, ring_ch, y);
                if (pos % chunk < chunk / 2u)
                    y = busfx_ring_read(stut, ring_ch, (uint8_t)(pos & (BFX_RING - 1u)));
            }
            ch[k][i] = y;
        }
        if (held && busfx_is_decay_gate(effect)) {
            s->follow += (peak - s->follow) * 0.002f;
            if (peak > s->follow * 1.7f && peak > 0.02f)
                s->gate += (1.0f - s->gate) * 0.3f;
            else
                s->gate += (0.0f - s->gate) * 0.0012f;
            if (s->gate < 0.0f)
                s->gate = 0.0f;
            if (s->gate > 1.0f)
                s->gate = 1.0f;
        } else if (held && busfx_is_rhythm(effect)) {
            float step = rg_tgt > s->gate ? rg_a : rg_r;
            s->gate += (rg_tgt - s->gate) * step;
            if (s->gate < 0.0f)
                s->gate = 0.0f;
            if (s->gate > 1.0f)
                s->gate = 1.0f;
        }
        if (s->gate < 1.0f)
            for (k = 0; k < nch; k++)
                ch[k][i] *= s->gate;
    }
}

#!/usr/bin/env python3
"""Interrupt production SMC consumers when they release a full queue slot.

The injected callback models the ISR producer running immediately after the
consumer publishes its read index. Queue code and producers come from the
selected production source; MIDI/UI actions alone are recorded substitutes.
SMC_SOURCE selects an unchanged base for the negative control.
"""
import os
from pathlib import Path
import re
import shlex
import subprocess
import tempfile

ROOT = Path(__file__).resolve().parents[2]
SOURCE = Path(os.environ.get("SMC_SOURCE", ROOT / "firmware/src/app/smc_mixer.c"))
source = SOURCE.read_text()


def function(name):
    match = re.search(r"^[^\n]*\b" + name + r"\([^\n]*\)\s*\{", source, re.M)
    if not match:
        raise RuntimeError(f"Production function not found: {name}")
    depth, end = 1, match.end()
    while depth:
        if end == len(source):
            raise RuntimeError(f"Unterminated production function: {name}")
        depth += (source[end] == "{") - (source[end] == "}")
        end += 1
    return source[match.start():end]


prefix = source[source.index("#define SMC_Q"):source.index("int smc_project_active")]
poll = function("smc_poll_peer" if "smc_poll_peer" in source else "smc_poll")
for index, name in enumerate(("smc_qr", "smc_host_r", "smc_mmc_r[src]")):
    statement = re.escape(name) + r" = \(uint8_t\)\(r \+ 1u\);"
    poll, matches = re.subn(statement, lambda m: m[0] + f" interleave({index});", poll)
    if matches != 1:
        raise RuntimeError(f"Expected one production publication for {name}, got {matches}")

harness = r'''
#include <assert.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include "app/smc_protocol.h"
#include "smc_fx_harness_stubs.h"
#define X0X_COLD
#define PROJ_BT_SMC_CENTRAL 16u
#define PROJ_BT_SMC_USER 32u
typedef struct { uint8_t kind, a, b, c; } pref_t;
enum { O_NONE, O_ASK, NKIT = 2 };
static struct { struct { uint8_t bt; } set; } proj;
static struct { uint8_t overlay, help; } ui;
static int locked, testing, inject, route, mmc_src, reset_on_first;
static unsigned count;
static uint8_t observed[64][7];
static int perf_testing(void) { return testing; }
static int ui_project_busy(void) { return locked; }
static void engine_smc_solo(int n) { (void)n; }
static void engine_smc_solo_targets(uint8_t p,uint16_t a,uint16_t b) { (void)a; (void)b; engine_smc_solo(p); }
static void ui_say(const char *a, const char *b) { (void)a; (void)b; }
''' + prefix + "\n" + "\n".join(function(name) for name in
    (name for name in ("smc_solo_union", "smc_peer_drop", "smc_ble_midi_slot", "smc_project_active", "smc_solo_clear") if re.search(r"\b" + name + r"\(", source))) + "\n" + "\n".join(function(name) for name in (
    "smc_project_drop", "smc_ble_midi", "smc_midi_host", "smc_mmc_host")) + r'''

static void record(const uint8_t *m, uint8_t n)
{
    assert(count < 64 && n <= 6);
    observed[count][0] = n;
    memcpy(observed[count] + 1, m, n);
    count++;
    if (reset_on_first && count == 1) smc_project_drop();
}
static uint8_t smc_message(const uint8_t *m, uint8_t n, int allow)
{
    assert(allow);
    record(m, n);
    return 0;
}
static void smc_guarded_button(uint8_t note, int mmc, int allow)
{
    assert(mmc && allow);
    record(&note, 1);
}
static void enqueue(unsigned i)
{
    if (route == 0) {
        /* Mixed lengths expose a torn length/payload as well as lost messages. */
        const uint8_t msg[6] = {0xF0, 0x7F, 0x7F, 6, (uint8_t)(i + 1), 0xF7};
        if ((i & 1) || i == SMC_Q) {
            const uint8_t cc[3] = {0xB0, 16, (uint8_t)(i + 1)};
            smc_ble_midi(cc, 3);
        } else smc_ble_midi(msg, 6);
    } else if (route == 1) {
        uint32_t pkt = 0x0Bu | (0xBFu << 8) | (16u << 16) | ((i + 1u) << 24);
        assert(smc_midi_host(pkt));
    } else smc_mmc_host((uint8_t)(i + 1), (uint8_t)mmc_src);
}
static void interleave(int queue)
{
    if (!inject || queue != (route == 4 ? 2 : route)) return;
    inject = 0;
    if (route == 4) {
        smc_mmc_host(33, (uint8_t)mmc_src); /* ISR refills the released slot */
        smc_mmc_host(34, (uint8_t)mmc_src); /* STOP overflows after PLAY */
    } else enqueue(route == 2 ? 16 : SMC_Q);
}
''' + function("smc_mmc_drain_stop") + "\n" + poll + ("\n" + function("smc_poll") if "smc_poll_peer" in source else "") + r'''

int main(int argc, char **argv)
{
    assert(argc == 5);
    route = atoi(argv[1]); mmc_src = atoi(argv[2]);
    unsigned start = (unsigned)atoi(argv[3]);
    reset_on_first = atoi(argv[4]);
    assert(route >= 0 && route <= 4 && mmc_src >= 0 && mmc_src < 2);
    smc_qr = smc_qw = smc_host_r = smc_host_w = (uint8_t)start;
    for (int i = 0; i < 2; i++) smc_mmc_r[i] = smc_mmc_w[i] = (uint8_t)start;
    smc.up = 1;
    proj.set.bt = PROJ_BT_SMC_CENTRAL | PROJ_BT_SMC_USER;
    if (route == 4) {
        /* ISR fills a freed slot with PLAY, then STOP overflows. The extra
         * PLAY predates STOP and must not be replayed after it next poll. */
        for (unsigned i = 0; i < 16; ++i) smc_mmc_host(33, (uint8_t)mmc_src);
        inject = 1;
        smc_poll();
        assert(!inject && count == 16u);
        for (unsigned i = 0; i < 16; ++i)
            assert(observed[i][0] == 1 && observed[i][1] == 0x5Eu);
        smc_mmc_host(33, (uint8_t)mmc_src); /* later PLAY belongs after STOP */
        smc_poll();
        assert(count == 19u);
        assert(observed[16][0] == 1 && observed[16][1] == 0x5Eu);
        assert(observed[17][0] == 1 && observed[17][1] == 0x5Du);
        assert(observed[18][0] == 1 && observed[18][1] == 0x5Eu);
        smc_poll();
        assert(count == 19u); /* STOP acknowledged only once */
        return 0;
    }
    if (route == 3) {
        /* First sixteen queued PLAY commands occupy the whole source ring.
         * The seventeenth STOP must run last, never be silently lost. */
        for (unsigned i = 0; i < 16; ++i) smc_mmc_host(33, (uint8_t)mmc_src);
        smc_mmc_host(34, (uint8_t)mmc_src);
        if (reset_on_first) {
            smc_project_drop(); /* a discarded project must not inherit STOP */
            smc_poll();
            assert(count == 0);
            return 0;
        }
        smc_poll();
        assert(count == 17);
        for (unsigned i = 0; i < 16; ++i)
            assert(observed[i][0] == 1 && observed[i][1] == 0x5E);
        assert(observed[16][0] == 1 && observed[16][1] == 0x5D);
        smc_poll();
        assert(count == 17); /* the lost STOP is acknowledged only once */
        return 0;
    }
    /* Only legitimate seven-bit payload bytes may become SMC controls.
     * Before this guard an invalid data1 0x88 was silently decoded as
     * Solo 1 (0x08), and invalid CC values were still accepted. */
    if (route == 1) {
        const uint32_t base = 0x0Bu | (0xBFu << 8);
        const uint32_t note = 0x09u | (0x9Fu << 8);
        uint8_t before = smc_host_w;
        assert(!smc_midi_host(base | (0x90u << 16) | (1u << 24)));
        assert(!smc_midi_host(base | (16u << 16) | (0x81u << 24)));
        assert(!smc_midi_host(note | (0x88u << 16) | (127u << 24)));
        assert(!smc_midi_host(note | (8u << 16) | (0xFFu << 24)));
        assert(smc_host_w == before);
        proj.set.bt &= (uint8_t)~PROJ_BT_SMC_USER;
        assert(!smc_midi_host(base | (16u << 16) | (1u << 24)));
        assert(smc_host_w == before);
        proj.set.bt |= PROJ_BT_SMC_USER;
    }
    unsigned capacity = route == 2 ? 16 : SMC_Q;
    for (unsigned i = 0; i < capacity; i++) enqueue(i);
    inject = 1;
    smc_poll();
    smc_poll();
    assert(!inject);
    unsigned expected_count = reset_on_first ? 1 : capacity + 1;
    assert(count == expected_count);
    for (unsigned i = 0; i < count; i++) {
        uint8_t expected[7] = {0};
        if (route == 0 && !(i & 1) && i != SMC_Q) {
            const uint8_t mmc[7] = {6, 0xF0, 0x7F, 0x7F, 6, (uint8_t)(i + 1), 0xF7};
            memcpy(expected, mmc, sizeof mmc);
        } else if (route == 2) {
            expected[0] = 1; expected[1] = smc_mmc_note((uint8_t)(i + 1));
        } else {
            expected[0] = 3; expected[1] = route == 0 ? 0xB0 : 0xBF;
            expected[2] = 16; expected[3] = (uint8_t)(i + 1);
        }
        if (memcmp(observed[i], expected, sizeof expected)) {
            fprintf(stderr, "FAIL: route=%d source=%d start=%u reset=%d event=%u: "
                    "queue slot was overwritten before dispatch\n",
                    route, mmc_src, start, reset_on_first, i);
            return 1;
        }
    }
    assert(smc_qr == smc_qw && smc_host_r == smc_host_w);
    for (int i = 0; i < 2; i++) assert(smc_mmc_r[i] == smc_mmc_w[i]);
    return 0;
}
'''

with tempfile.TemporaryDirectory(prefix="smc-queue-") as tmp:
    c = Path(tmp) / "test.c"
    executable = Path(tmp) / "test"
    c.write_text(harness)
    flags = shlex.split(os.environ.get("SAN_FLAGS", ""))
    subprocess.run([os.environ.get("CC", "cc"), "-std=c99", "-O2", "-g",
                    "-Wall", "-Wextra", "-Werror", *flags,
                    "-I" + str(ROOT / "firmware/src"),
                    "-I" + str(ROOT / "tests/host"),
                    str(c), "-o", str(executable)], check=True)
    failures = []
    cases = 0
    for route, src in ((0, 0), (1, 0), (2, 0), (2, 1), (3, 0), (3, 1), (4, 0), (4, 1)):
        for start in (0, 240, 255):
            for reset in (0, 1):
                if route == 4 and reset: continue
                args = [str(route), str(src), str(start), str(reset)]
                result = subprocess.run([str(executable), *args], check=False)
                cases += 1
                if result.returncode:
                    failures.append((args, result.returncode))
    if failures:
        raise SystemExit(f"FAIL: {len(failures)}/{cases} SMC queue interleavings: {failures}")
print(f"PASS: {cases} full-queue ISR interleavings, MMC STOP priority, wrap and reset discard")
